// Categoria de cada alimento é uma propriedade de código (não persistida em Storage),
// então funciona pra qualquer usuário mesmo que seu alimentos_biblioteca já sincronizado
// tenha sido salvo antes desse campo existir (mergeSeeds nunca atualiza itens já existentes).
const _categoriaPorNome = new Map(
  ALIMENTOS_PADRAO.map(f => [f.name.trim().toLowerCase(), f.categoria || null])
);
function getCategoriaAlimento(name) {
  return _categoriaPorNome.get((name || '').trim().toLowerCase()) || null;
}
